mapper.select:
SELECT c.id AS categoryId, c.name AS label, COALESCE(SUM(CASE WHEN o.status IN (1, 2, 3, 4) THEN oi.total_price ELSE 0 END), 0) AS salesAmount, COUNT(DISTINCT CASE WHEN o.status IN (1, 2, 3, 4) THEN o.id END) AS orderCount, COALESCE(SUM(CASE WHEN o.status IN (1, 2, 3, 4) THEN oi.quantity ELSE 0 END), 0) AS quantity, COALESCE(SUM(CASE WHEN o.status = 7 THEN oi.total_price ELSE 0 END), 0) AS refundAmount, COALESCE(AVG(CASE WHEN o.status IN (1, 2, 3, 4) THEN o.pay_amount END), 0) AS averageOrderAmount FROM category c LEFT JOIN product p ON p.category_id = c.id LEFT JOIN order_item oi ON oi.product_id = p.id LEFT JOIN `order` o ON o.id = oi.order_id AND o.status IN (1, 2, 3, 4, 7)
AND c.id = #{categoryId} AND o.create_time >= #{startTime} AND o.create_time <= #{endTime}
GROUP BY c.id, c.name ORDER BY salesAmount DESC

SELECT p.id AS productId, p.name AS label, COALESCE(SUM(oi.total_price), 0) AS salesAmount, COALESCE(SUM(oi.quantity), 0) AS quantity, COUNT(DISTINCT o.id) AS orderCount FROM product p INNER JOIN order_item oi ON oi.product_id = p.id INNER JOIN `order` o ON o.id = oi.order_id AND o.status IN (1, 2, 3, 4)
AND p.category_id = #{categoryId} AND o.create_time >= #{startTime} AND o.create_time <= #{endTime}
GROUP BY p.id, p.name ORDER BY quantity DESC, salesAmount DESC LIMIT #{limit}
